-- Hotel Mami Vilma (Roboré, Santa Cruz): first partner from the hotel information sheet (ficha TRIPY001, 25/10/2026).
-- Public rates, no Tripya discount yet. Content in Spanish plus translations for every site language.
-- Photos: Roboré and surroundings from Wikimedia Commons until the hotel's own photos are uploaded in admin.

insert into public.destinations (country_code, name, slug, kind, description, image_url, is_published, sort_order, translations)
values ('BO', 'Roboré', 'robore', 'city', 'Puerta de la Chiquitania: serranías, cascadas, aguas termales y pueblos como Chochís y Santiago de Chiquitos.',
  'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Torre_de_Choch%C3%ADs_y_Cerro_Choch%C3%ADs_de_fondo_-_Robor%C3%A9%2C_Bolivia.jpg/1280px-Torre_de_Choch%C3%ADs_y_Cerro_Choch%C3%ADs_de_fondo_-_Robor%C3%A9%2C_Bolivia.jpg',
  true, 16, '{"en": {"name": "Roboré", "description": "Gateway to the Chiquitania: mountain ranges, waterfalls, hot springs and villages such as Chochís and Santiago de Chiquitos."}, "fr": {"name": "Roboré", "description": "Porte de la Chiquitanía : serranías, cascades, sources chaudes et villages comme Chochís et Santiago de Chiquitos."}, "pt": {"name": "Roboré", "description": "Porta de entrada da Chiquitania: serras, cachoeiras, águas termais e vilarejos como Chochís e Santiago de Chiquitos."}, "de": {"name": "Roboré", "description": "Tor zur Chiquitanía: Bergketten, Wasserfälle, heiße Quellen und Dörfer wie Chochís und Santiago de Chiquitos."}, "zh": {"name": "Roboré", "description": "奇基塔尼亚的门户：山脉、瀑布、温泉以及乔奇斯和圣地亚哥德奇基托斯等小镇。"}, "ja": {"name": "Roboré", "description": "チキタニアの玄関口。山並み、滝、温泉、そしてチョチスやサンティアゴ・デ・チキートスなどの村々。"}, "ko": {"name": "Roboré", "description": "치키타니아의 관문: 산맥, 폭포, 온천, 그리고 초치스와 산티아고 데 치키토스 같은 마을."}}'::jsonb)
on conflict (slug) do nothing;

-- Partner (owned by the first admin, like the other partners created from the panel).
insert into public.providers (owner_id, legal_name, trade_name, email, phone, partner_type, contact_name, city, address, country_code, status, notes)
select r.user_id, 'Hotel Mami Vilma', 'Hotel Mami Vilma', 'reservasmamivilma@gmail.com', '+591 77555508', 'hotel',
  'Sophia Dayanna Moreno Salvatierra (comercial)', 'Roboré', 'Av. Ingavi N.º 250, a 3 cuadras de la plaza principal', 'BO', 'approved',
  'Ficha TRIPY001 (recopilada el 25/10/2026). Verificada el 29/10/2026 por Aracely Mealla Lerma: documentos verificados, fotos y logo recibidos, autorización de uso de fotos confirmada. Facebook: https://www.facebook.com/HotelMamiVilma · Fotos: https://drive.google.com/drive/folders/1gwC9q0C23oJJjIyRr4ZFgxCwlkDOX39J · Pendiente: tarifa negociada con Tripya, comisión y condiciones propias de reserva/cancelación.'
from public.user_roles r
where r.role = 'admin' and not exists (select 1 from public.providers where trade_name = 'Hotel Mami Vilma')
order by r.user_id
limit 1;

with ins as (
  insert into public.products (provider_id, destination_id, type, slug, title, description, currency_code, base_price_minor, duration_label, includes,
    property_type, pricing_unit, capacity_max, min_nights, amenities, booking_conditions, cancellation_policy, check_in_time, check_out_time,
    address, latitude, longitude, google_maps_url, verified_at, verification_summary, restrictions, perks, location_note, nearby_places, room_options,
    translations, is_published, is_sample)
  select pv.id, d.id, 'accommodation'::public.product_type, 'hotel-mami-vilma-robore', 'Hotel Mami Vilma', 'El Hotel Mami Vilma es un alojamiento acogedor y familiar en Roboré, ideal para familias, parejas y grupos que buscan tranquilidad, comodidad y un lugar donde descansar mientras descubren los atractivos naturales de la región.

Está a tres cuadras de la plaza principal, así que tendrás a mano comercios, restaurantes y servicios. Después de un día de excursiones a Chochís, Santiago de Chiquitos o Aguas Calientes, podrás relajarte en el jardín y el patio, descansar en las hamacas y disfrutar de un ambiente tranquilo.

El hotel tiene habitaciones para cada tipo de viaje, desde individuales hasta familiares para 6 personas, además de restaurante, cocina equipada y estacionamiento dentro del predio.

Consejo: lleva efectivo en bolivianos (Bs), porque algunos comercios de la zona no aceptan tarjetas ni otras monedas.

Fotos de Roboré y alrededores (no del hotel): Ruditaly (CC BY-SA 4.0), vía Wikimedia Commons.', 'BOB', 25000,
    'Desayuno incluido · hasta 6 personas por habitación', array['Agua caliente', 'Televisión satelital', 'Ropa de cama y mantas', 'Limpieza de la habitación', 'Hamacas en el jardín']::text[],
    'hostel', 'per_night', 6, 1, array['wifi', 'breakfast', 'parking', 'air_conditioning', 'restaurant', 'kitchen', 'garden', 'pets']::text[], 'Te confirmamos la disponibilidad con el hotel antes del pago. Se requiere un anticipo mínimo del 50 % del total. Pagos en efectivo, QR o transferencia bancaria. Los cambios están sujetos a disponibilidad y pueden variar el precio. No hay impuestos adicionales.', 'Cancelación gratuita hasta 48 horas antes del check-in. Si cancelas después de ese plazo o no te presentas, se cobra el 100 % de la primera noche.', '14:00', '12:00',
    'Av. Ingavi N.º 250, Roboré, Santa Cruz', -18.332938, -59.756795, 'https://www.google.com/maps/place/Hotel+Mami+Vilma/@-18.3324736,-59.7567953,17z/data=!4m9!3m8!1s0x938ea94e0a0025a9:0xc401c321592aa67f', '2026-10-29T12:00:00Z',
    'Información y documentos del alojamiento verificados por el equipo Tripya el 29/10/2026.',
    array['Se admiten mascotas pequeñas; para mascotas grandes se pide una garantía (consúltanos)', 'Recepción abierta de 06:00 a 23:00', 'Algunas habitaciones tienen dos escalones y no hay rampas', 'No hay cunas ni equipamiento para bebés', 'El hotel no se responsabiliza por objetos de valor no declarados']::text[], array['Regalo de bienvenida de Tripya al llegar']::text[], 'A 3 cuadras de la plaza principal de Roboré', '[{"name": "Plaza principal e iglesia de Roboré", "minutes": 4, "mode": "walk"}, {"name": "Banco Unión y Cooperativa San Martín de Porres", "minutes": 5, "mode": "walk"}, {"name": "Mercado municipal", "minutes": 6, "mode": "walk"}, {"name": "Terminal de buses", "minutes": 8, "mode": "car"}, {"name": "Santiago de Chiquitos", "minutes": 30, "mode": "car"}, {"name": "Aguas Calientes", "minutes": 35, "mode": "car"}, {"name": "Chochís", "minutes": 45, "mode": "car"}]'::jsonb, '[{"id": "individual", "name": "Habitación individual", "description": "Para una persona que viaja sola.", "image_url": null, "features": ["Baño privado", "Aire acondicionado", "TV satelital", "Escritorio"], "beds": null, "size_m2": null, "max_guests": 1, "supplement_minor": 0}, {"id": "doble", "name": "Habitación doble o matrimonial", "description": "Ideal para parejas o dos amigos.", "image_url": null, "features": ["Baño privado", "Aire acondicionado", "TV satelital", "Escritorio"], "beds": null, "size_m2": null, "max_guests": 2, "supplement_minor": 11000}, {"id": "triple", "name": "Habitación triple", "description": "Para tres personas.", "image_url": null, "features": ["Baño privado", "Aire acondicionado", "TV satelital", "Escritorio"], "beds": null, "size_m2": null, "max_guests": 3, "supplement_minor": 21000}, {"id": "cuadruple", "name": "Habitación cuádruple", "description": "Para familias o grupos de cuatro.", "image_url": null, "features": ["Baño privado", "Aire acondicionado", "TV satelital", "Escritorio"], "beds": null, "size_m2": null, "max_guests": 4, "supplement_minor": 29000}, {"id": "familiar", "name": "Habitación familiar", "description": "Ideal para familias y grupos de hasta 6 personas.", "image_url": null, "features": ["Baño privado", "Aire acondicionado", "TV satelital", "Escritorio"], "beds": null, "size_m2": null, "max_guests": 6, "supplement_minor": 60000}]'::jsonb,
    '{"en": {"title": "Hotel Mami Vilma", "description": "Hotel Mami Vilma is a cosy, family-run place to stay in Roboré, ideal for families, couples and groups looking for peace, comfort and somewhere to rest while discovering the region''s natural attractions.\n\nIt is three blocks from the main square, so shops, restaurants and services are close at hand. After a day trip to Chochís, Santiago de Chiquitos or Aguas Calientes, you can relax in the garden and patio, rest in the hammocks and enjoy a quiet atmosphere.\n\nThe hotel has rooms for every kind of trip, from singles to family rooms for 6 people, plus a restaurant, a fully equipped kitchen and on-site parking.\n\nTip: bring cash in bolivianos (Bs), as some shops in the area don''t accept cards or other currencies.\n\nPhotos of Roboré and its surroundings (not of the hotel): Ruditaly (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "Breakfast included · up to 6 guests per room", "includes": ["Hot water", "Satellite TV", "Bed linen and blankets", "Room cleaning", "Hammocks in the garden"], "restrictions": ["Small pets are welcome; large pets require a deposit (ask us)", "Reception open from 06:00 to 23:00", "Some rooms have two steps and there are no ramps", "No cots or baby equipment", "The hotel is not responsible for undeclared valuables"], "perks": ["Tripya welcome gift on arrival"], "booking_conditions": "We confirm availability with the hotel before you pay. A minimum deposit of 50% of the total is required. Payment in cash, by QR or by bank transfer. Changes are subject to availability and may change the price. No additional taxes.", "cancellation_policy": "Free cancellation up to 48 hours before check-in. If you cancel after that or don''t show up, 100% of the first night is charged.", "location_note": "3 blocks from Roboré''s main square", "nearby_names": ["Main square and church of Roboré", "Banco Unión and San Martín de Porres credit union", "Municipal market", "Bus terminal", "Santiago de Chiquitos", "Aguas Calientes", "Chochís"], "rooms": {"individual": {"name": "Single room", "description": "For one person travelling alone.", "features": ["Private bathroom", "Air conditioning", "Satellite TV", "Desk"]}, "doble": {"name": "Double room", "description": "Ideal for couples or two friends.", "features": ["Private bathroom", "Air conditioning", "Satellite TV", "Desk"]}, "triple": {"name": "Triple room", "description": "For three people.", "features": ["Private bathroom", "Air conditioning", "Satellite TV", "Desk"]}, "cuadruple": {"name": "Quadruple room", "description": "For families or groups of four.", "features": ["Private bathroom", "Air conditioning", "Satellite TV", "Desk"]}, "familiar": {"name": "Family room", "description": "Ideal for families and groups of up to 6 people.", "features": ["Private bathroom", "Air conditioning", "Satellite TV", "Desk"]}}}, "fr": {"title": "Hotel Mami Vilma", "description": "L''Hôtel Mami Vilma est un hébergement chaleureux et familial à Roboré, idéal pour les familles, les couples et les groupes qui cherchent le calme, le confort et un endroit où se reposer en découvrant les attraits naturels de la région.\n\nIl se trouve à trois rues de la place principale : commerces, restaurants et services sont à portée de main. Après une excursion à Chochís, Santiago de Chiquitos ou Aguas Calientes, tu pourras te détendre dans le jardin et le patio, te reposer dans les hamacs et profiter d''une ambiance paisible.\n\nL''hôtel propose des chambres pour chaque type de voyage, de la chambre individuelle à la chambre familiale pour 6 personnes, ainsi qu''un restaurant, une cuisine équipée et un parking sur place.\n\nConseil : emporte des espèces en bolivianos (Bs), car certains commerces de la région n''acceptent ni les cartes ni d''autres devises.\n\nPhotos de Roboré et des environs (pas de l''hôtel) : Ruditaly (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "Petit-déjeuner inclus · jusqu''à 6 personnes par chambre", "includes": ["Eau chaude", "Télévision par satellite", "Draps et couvertures", "Ménage de la chambre", "Hamacs dans le jardin"], "restrictions": ["Petits animaux acceptés ; pour les grands animaux, une caution est demandée (renseigne-toi)", "Réception ouverte de 06:00 à 23:00", "Certaines chambres ont deux marches et il n''y a pas de rampe", "Pas de lit bébé ni d''équipement pour bébés", "L''hôtel n''est pas responsable des objets de valeur non déclarés"], "perks": ["Cadeau de bienvenue Tripya à l''arrivée"], "booking_conditions": "Nous confirmons la disponibilité avec l''hôtel avant le paiement. Un acompte minimum de 50 % du total est demandé. Paiement en espèces, par QR ou par virement bancaire. Les modifications dépendent de la disponibilité et peuvent changer le prix. Pas de taxes supplémentaires.", "cancellation_policy": "Annulation gratuite jusqu''à 48 heures avant l''arrivée. En cas d''annulation après ce délai ou de non-présentation, 100 % de la première nuit est facturé.", "location_note": "À 3 rues de la place principale de Roboré", "nearby_names": ["Place principale et église de Roboré", "Banco Unión et coopérative San Martín de Porres", "Marché municipal", "Gare routière", "Santiago de Chiquitos", "Aguas Calientes", "Chochís"], "rooms": {"individual": {"name": "Chambre individuelle", "description": "Pour une personne qui voyage seule.", "features": ["Salle de bain privée", "Climatisation", "TV par satellite", "Bureau"]}, "doble": {"name": "Chambre double", "description": "Idéale pour les couples ou deux amis.", "features": ["Salle de bain privée", "Climatisation", "TV par satellite", "Bureau"]}, "triple": {"name": "Chambre triple", "description": "Pour trois personnes.", "features": ["Salle de bain privée", "Climatisation", "TV par satellite", "Bureau"]}, "cuadruple": {"name": "Chambre quadruple", "description": "Pour les familles ou groupes de quatre.", "features": ["Salle de bain privée", "Climatisation", "TV par satellite", "Bureau"]}, "familiar": {"name": "Chambre familiale", "description": "Idéale pour les familles et groupes jusqu''à 6 personnes.", "features": ["Salle de bain privée", "Climatisation", "TV par satellite", "Bureau"]}}}, "pt": {"title": "Hotel Mami Vilma", "description": "O Hotel Mami Vilma é uma hospedagem aconchegante e familiar em Roboré, ideal para famílias, casais e grupos que buscam tranquilidade, conforto e um lugar para descansar enquanto descobrem as atrações naturais da região.\n\nFica a três quadras da praça principal, então você terá comércio, restaurantes e serviços por perto. Depois de um dia de passeio a Chochís, Santiago de Chiquitos ou Aguas Calientes, você pode relaxar no jardim e no pátio, descansar nas redes e aproveitar um ambiente tranquilo.\n\nO hotel tem quartos para todo tipo de viagem, de individuais a familiares para 6 pessoas, além de restaurante, cozinha equipada e estacionamento no local.\n\nDica: leve dinheiro em bolivianos (Bs), pois alguns comércios da região não aceitam cartões nem outras moedas.\n\nFotos de Roboré e arredores (não do hotel): Ruditaly (CC BY-SA 4.0), via Wikimedia Commons.", "duration_label": "Café da manhã incluído · até 6 pessoas por quarto", "includes": ["Água quente", "TV via satélite", "Roupa de cama e cobertores", "Limpeza do quarto", "Redes no jardim"], "restrictions": ["Animais de pequeno porte são aceitos; para animais grandes é pedida uma garantia (consulte-nos)", "Recepção aberta das 06:00 às 23:00", "Alguns quartos têm dois degraus e não há rampas", "Não há berços nem equipamentos para bebês", "O hotel não se responsabiliza por objetos de valor não declarados"], "perks": ["Presente de boas-vindas da Tripya na chegada"], "booking_conditions": "Confirmamos a disponibilidade com o hotel antes do pagamento. É necessário um sinal mínimo de 50 % do total. Pagamento em dinheiro, QR ou transferência bancária. Alterações estão sujeitas à disponibilidade e podem mudar o preço. Não há impostos adicionais.", "cancellation_policy": "Cancelamento gratuito até 48 horas antes do check-in. Se cancelar depois desse prazo ou não comparecer, será cobrado 100 % da primeira noite.", "location_note": "A 3 quadras da praça principal de Roboré", "nearby_names": ["Praça principal e igreja de Roboré", "Banco Unión e Cooperativa San Martín de Porres", "Mercado municipal", "Rodoviária", "Santiago de Chiquitos", "Aguas Calientes", "Chochís"], "rooms": {"individual": {"name": "Quarto individual", "description": "Para uma pessoa viajando sozinha.", "features": ["Banheiro privativo", "Ar-condicionado", "TV via satélite", "Escrivaninha"]}, "doble": {"name": "Quarto duplo ou de casal", "description": "Ideal para casais ou dois amigos.", "features": ["Banheiro privativo", "Ar-condicionado", "TV via satélite", "Escrivaninha"]}, "triple": {"name": "Quarto triplo", "description": "Para três pessoas.", "features": ["Banheiro privativo", "Ar-condicionado", "TV via satélite", "Escrivaninha"]}, "cuadruple": {"name": "Quarto quádruplo", "description": "Para famílias ou grupos de quatro.", "features": ["Banheiro privativo", "Ar-condicionado", "TV via satélite", "Escrivaninha"]}, "familiar": {"name": "Quarto familiar", "description": "Ideal para famílias e grupos de até 6 pessoas.", "features": ["Banheiro privativo", "Ar-condicionado", "TV via satélite", "Escrivaninha"]}}}, "de": {"title": "Hotel Mami Vilma", "description": "Das Hotel Mami Vilma ist eine gemütliche, familiäre Unterkunft in Roboré – ideal für Familien, Paare und Gruppen, die Ruhe, Komfort und einen Ort zum Erholen suchen, während sie die Naturschönheiten der Region entdecken.\n\nEs liegt drei Straßenblöcke vom Hauptplatz entfernt, sodass Geschäfte, Restaurants und Dienstleistungen gleich in der Nähe sind. Nach einem Ausflug nach Chochís, Santiago de Chiquitos oder Aguas Calientes kannst du im Garten und Innenhof entspannen, in den Hängematten ausruhen und die ruhige Atmosphäre genießen.\n\nDas Hotel bietet Zimmer für jede Art von Reise, vom Einzelzimmer bis zum Familienzimmer für 6 Personen, dazu ein Restaurant, eine voll ausgestattete Küche und Parkplätze auf dem Gelände.\n\nTipp: Nimm Bargeld in Bolivianos (Bs) mit, da manche Geschäfte in der Gegend weder Karten noch andere Währungen akzeptieren.\n\nFotos von Roboré und Umgebung (nicht vom Hotel): Ruditaly (CC BY-SA 4.0), über Wikimedia Commons.", "duration_label": "Frühstück inklusive · bis zu 6 Personen pro Zimmer", "includes": ["Warmwasser", "Satelliten-TV", "Bettwäsche und Decken", "Zimmerreinigung", "Hängematten im Garten"], "restrictions": ["Kleine Haustiere sind erlaubt; für große Haustiere wird eine Kaution verlangt (frag uns)", "Rezeption geöffnet von 06:00 bis 23:00 Uhr", "Einige Zimmer haben zwei Stufen, es gibt keine Rampen", "Keine Babybetten oder Babyausstattung", "Das Hotel haftet nicht für nicht angemeldete Wertgegenstände"], "perks": ["Willkommensgeschenk von Tripya bei der Ankunft"], "booking_conditions": "Wir bestätigen die Verfügbarkeit mit dem Hotel, bevor du bezahlst. Es ist eine Anzahlung von mindestens 50 % des Gesamtbetrags erforderlich. Zahlung in bar, per QR-Code oder per Banküberweisung. Änderungen hängen von der Verfügbarkeit ab und können den Preis verändern. Keine zusätzlichen Steuern.", "cancellation_policy": "Kostenlose Stornierung bis 48 Stunden vor dem Check-in. Bei späterer Stornierung oder Nichterscheinen werden 100 % der ersten Nacht berechnet.", "location_note": "3 Straßenblöcke vom Hauptplatz von Roboré", "nearby_names": ["Hauptplatz und Kirche von Roboré", "Banco Unión und Genossenschaftsbank San Martín de Porres", "Städtischer Markt", "Busbahnhof", "Santiago de Chiquitos", "Aguas Calientes", "Chochís"], "rooms": {"individual": {"name": "Einzelzimmer", "description": "Für eine allein reisende Person.", "features": ["Eigenes Bad", "Klimaanlage", "Satelliten-TV", "Schreibtisch"]}, "doble": {"name": "Doppelzimmer", "description": "Ideal für Paare oder zwei Freunde.", "features": ["Eigenes Bad", "Klimaanlage", "Satelliten-TV", "Schreibtisch"]}, "triple": {"name": "Dreibettzimmer", "description": "Für drei Personen.", "features": ["Eigenes Bad", "Klimaanlage", "Satelliten-TV", "Schreibtisch"]}, "cuadruple": {"name": "Vierbettzimmer", "description": "Für Familien oder Gruppen zu viert.", "features": ["Eigenes Bad", "Klimaanlage", "Satelliten-TV", "Schreibtisch"]}, "familiar": {"name": "Familienzimmer", "description": "Ideal für Familien und Gruppen bis zu 6 Personen.", "features": ["Eigenes Bad", "Klimaanlage", "Satelliten-TV", "Schreibtisch"]}}}, "zh": {"title": "Hotel Mami Vilma", "description": "Mami Vilma 酒店是位于罗沃雷（Roboré）的一家温馨的家庭式住宿，非常适合在探索当地自然风光时寻求宁静、舒适和休息之处的家庭、情侣和团体。\n\n酒店距离主广场仅三个街区，商店、餐厅和各类服务近在咫尺。白天游览完乔奇斯（Chochís）、圣地亚哥德奇基托斯（Santiago de Chiquitos）或阿瓜斯卡连特斯（Aguas Calientes）后，你可以在花园和庭院里放松，躺在吊床上休息，享受安静的氛围。\n\n酒店提供适合各种出行方式的房间，从单人间到可住 6 人的家庭房，还设有餐厅、设备齐全的厨房和院内停车场。\n\n小贴士：请携带玻利维亚诺（Bs）现金，因为当地部分商店不接受银行卡或其他货币。\n\n罗沃雷及周边照片（非酒店照片）：Ruditaly（CC BY-SA 4.0），来自 Wikimedia Commons。", "duration_label": "含早餐 · 每间房最多 6 人", "includes": ["热水", "卫星电视", "床品和毛毯", "客房清洁", "花园吊床"], "restrictions": ["可携带小型宠物；大型宠物需支付押金（请咨询我们）", "前台开放时间 06:00 至 23:00", "部分房间需上两级台阶，无无障碍坡道", "不提供婴儿床或婴儿用品", "酒店不对未申报的贵重物品负责"], "perks": ["抵达时赠送 Tripya 欢迎礼物"], "booking_conditions": "付款前我们会先与酒店确认是否可订。需支付至少总价 50% 的定金。可使用现金、二维码或银行转账付款。修改预订视可订情况而定，价格可能变动。无额外税费。", "cancellation_policy": "入住前 48 小时可免费取消。超过该期限取消或未入住，将收取首晚房费的 100%。", "location_note": "距罗沃雷主广场 3 个街区", "nearby_names": ["罗沃雷主广场和教堂", "Banco Unión 银行和 San Martín de Porres 信用合作社", "市政市场", "长途汽车站", "圣地亚哥德奇基托斯", "阿瓜斯卡连特斯", "乔奇斯"], "rooms": {"individual": {"name": "单人间", "description": "适合独自旅行的人。", "features": ["独立卫浴", "空调", "卫星电视", "书桌"]}, "doble": {"name": "双人间 / 大床房", "description": "适合情侣或两位朋友。", "features": ["独立卫浴", "空调", "卫星电视", "书桌"]}, "triple": {"name": "三人间", "description": "可住三人。", "features": ["独立卫浴", "空调", "卫星电视", "书桌"]}, "cuadruple": {"name": "四人间", "description": "适合四人家庭或团体。", "features": ["独立卫浴", "空调", "卫星电视", "书桌"]}, "familiar": {"name": "家庭房", "description": "适合最多 6 人的家庭和团体。", "features": ["独立卫浴", "空调", "卫星电视", "书桌"]}}}, "ja": {"title": "Hotel Mami Vilma", "description": "ホテル・マミ・ビルマは、ロボレにある居心地のよい家族経営の宿です。地域の自然を巡りながら、静かでくつろげる滞在先を探しているご家族、カップル、グループに最適です。\n\n中央広場から 3 ブロックの距離にあり、お店やレストラン、各種サービスがすぐ近くにそろっています。チョチス、サンティアゴ・デ・チキートス、アグアス・カリエンテスへの観光を楽しんだ後は、庭やパティオでくつろいだり、ハンモックで休んだりと、穏やかな時間を過ごせます。\n\nシングルから最大 6 名のファミリールームまで、旅のスタイルに合わせた客室を用意しているほか、レストラン、設備の整ったキッチン、敷地内駐車場もあります。\n\nアドバイス：周辺にはカードや外貨が使えないお店もあるため、ボリビアーノ（Bs）の現金をご用意ください。\n\nロボレと周辺の写真（ホテルの写真ではありません）：Ruditaly（CC BY-SA 4.0）、Wikimedia Commons より。", "duration_label": "朝食付き · 1 室最大 6 名", "includes": ["温水シャワー", "衛星テレビ", "寝具・毛布", "客室清掃", "庭のハンモック"], "restrictions": ["小型のペットは同伴可。大型のペットはデポジットが必要です（お問い合わせください）", "フロント営業時間 06:00〜23:00", "一部の客室は 2 段の段差があり、スロープはありません", "ベビーベッドなどの乳幼児用設備はありません", "申告されていない貴重品について、ホテルは責任を負いません"], "perks": ["到着時に Tripya からのウェルカムギフト"], "booking_conditions": "お支払いの前に、ホテルに空き状況を確認します。合計金額の 50% 以上の前払いが必要です。お支払いは現金、QR コード、銀行振込が利用できます。変更は空き状況によるもので、料金が変わる場合があります。追加の税金はありません。", "cancellation_policy": "チェックインの 48 時間前まで無料でキャンセルできます。それ以降のキャンセルや無断不泊の場合は、1 泊目の料金の 100% が請求されます。", "location_note": "ロボレの中央広場から 3 ブロック", "nearby_names": ["ロボレの中央広場と教会", "ウニオン銀行とサン・マルティン・デ・ポレス信用組合", "市場", "バスターミナル", "サンティアゴ・デ・チキートス", "アグアス・カリエンテス", "チョチス"], "rooms": {"individual": {"name": "シングルルーム", "description": "おひとりでの旅に。", "features": ["専用バスルーム", "エアコン", "衛星テレビ", "デスク"]}, "doble": {"name": "ダブルルーム", "description": "カップルや友人 2 名に最適。", "features": ["専用バスルーム", "エアコン", "衛星テレビ", "デスク"]}, "triple": {"name": "トリプルルーム", "description": "3 名様向け。", "features": ["専用バスルーム", "エアコン", "衛星テレビ", "デスク"]}, "cuadruple": {"name": "4 人部屋", "description": "4 名のご家族やグループに。", "features": ["専用バスルーム", "エアコン", "衛星テレビ", "デスク"]}, "familiar": {"name": "ファミリールーム", "description": "最大 6 名のご家族やグループに最適。", "features": ["専用バスルーム", "エアコン", "衛星テレビ", "デスク"]}}}, "ko": {"title": "Hotel Mami Vilma", "description": "호텔 마미 빌마는 로보레에 있는 아늑한 가족 운영 숙소로, 지역의 자연을 둘러보며 편안하게 쉴 곳을 찾는 가족, 커플, 단체 여행객에게 잘 맞습니다.\n\n중앙 광장에서 세 블록 거리에 있어 상점, 식당, 각종 편의시설이 가깝습니다. 초치스, 산티아고 데 치키토스, 아구아스 칼리엔테스를 다녀온 뒤에는 정원과 안뜰에서 쉬거나 해먹에 누워 조용한 분위기를 즐길 수 있습니다.\n\n1인실부터 최대 6명이 묵는 가족실까지 여행 스타일에 맞는 객실이 있으며, 레스토랑, 설비를 갖춘 주방, 단지 내 주차장도 있습니다.\n\n팁: 주변에는 카드나 외화를 받지 않는 상점도 있으니 볼리비아노(Bs) 현금을 준비하세요.\n\n로보레와 주변 지역 사진(호텔 사진 아님): Ruditaly (CC BY-SA 4.0), Wikimedia Commons 제공.", "duration_label": "조식 포함 · 객실당 최대 6명", "includes": ["온수", "위성 TV", "침구 및 담요", "객실 청소", "정원 해먹"], "restrictions": ["소형 반려동물은 동반 가능하며, 대형 반려동물은 보증금이 필요해요(문의해 주세요)", "프런트 운영 시간 06:00~23:00", "일부 객실은 계단 두 칸이 있고 경사로는 없어요", "아기 침대 및 유아용품이 없어요", "신고하지 않은 귀중품에 대해 호텔은 책임지지 않아요"], "perks": ["도착 시 Tripya 웰컴 선물"], "booking_conditions": "결제 전에 호텔에 예약 가능 여부를 확인해 드려요. 총액의 최소 50%를 선금으로 내야 해요. 현금, QR 코드, 계좌 이체로 결제할 수 있어요. 변경은 예약 상황에 따라 가능하며 요금이 달라질 수 있어요. 추가 세금은 없어요.", "cancellation_policy": "체크인 48시간 전까지 무료 취소가 가능해요. 이후 취소하거나 노쇼인 경우 첫날 숙박 요금의 100%가 청구돼요.", "location_note": "로보레 중앙 광장에서 3블록", "nearby_names": ["로보레 중앙 광장과 성당", "우니온 은행과 산 마르틴 데 포레스 신용협동조합", "시립 시장", "버스 터미널", "산티아고 데 치키토스", "아구아스 칼리엔테스", "초치스"], "rooms": {"individual": {"name": "1인실", "description": "혼자 여행하는 분께 알맞아요.", "features": ["전용 욕실", "에어컨", "위성 TV", "책상"]}, "doble": {"name": "더블룸", "description": "커플이나 친구 두 명에게 좋아요.", "features": ["전용 욕실", "에어컨", "위성 TV", "책상"]}, "triple": {"name": "트리플룸", "description": "3명이 묵을 수 있어요.", "features": ["전용 욕실", "에어컨", "위성 TV", "책상"]}, "cuadruple": {"name": "4인실", "description": "4인 가족이나 단체에 알맞아요.", "features": ["전용 욕실", "에어컨", "위성 TV", "책상"]}, "familiar": {"name": "가족실", "description": "최대 6명의 가족과 단체에 좋아요.", "features": ["전용 욕실", "에어컨", "위성 TV", "책상"]}}}}'::jsonb, true, false
  from public.providers pv
  join public.destinations d on d.slug = 'robore'
  where pv.trade_name = 'Hotel Mami Vilma'
  on conflict (slug) do nothing
  returning id
), media as (
  insert into public.product_media (product_id, storage_path, public_url, alt_text, sort_order)
  select ins.id, m.path, m.url, m.alt, m.ord from ins cross join (values
    ('external/wikimedia/Plaza Ángel Sandóval de Roboré - Chiquitos, Bolivia.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Plaza_%C3%81ngel_Sand%C3%B3val_de_Robor%C3%A9_-_Chiquitos%2C_Bolivia.jpg/1280px-Plaza_%C3%81ngel_Sand%C3%B3val_de_Robor%C3%A9_-_Chiquitos%2C_Bolivia.jpg', 'Plaza principal de Roboré', 0),
    ('external/wikimedia/Torre de Chochís y Cerro Chochís de fondo - Roboré, Bolivia.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Torre_de_Choch%C3%ADs_y_Cerro_Choch%C3%ADs_de_fondo_-_Robor%C3%A9%2C_Bolivia.jpg/1280px-Torre_de_Choch%C3%ADs_y_Cerro_Choch%C3%ADs_de_fondo_-_Robor%C3%A9%2C_Bolivia.jpg', 'Torre de Chochís, cerca de Roboré', 1),
    ('external/wikimedia/Aguas Calientes - Roboré, Bolivia.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Aguas_Calientes_-_Robor%C3%A9%2C_Bolivia.jpg/1280px-Aguas_Calientes_-_Robor%C3%A9%2C_Bolivia.jpg', 'Aguas termales de Aguas Calientes, cerca de Roboré', 2),
    ('external/wikimedia/Santiago de Chiquitos y la Serranía de Santiago - Chiquitos, Bolivia.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Santiago_de_Chiquitos_y_la_Serran%C3%ADa_de_Santiago_-_Chiquitos%2C_Bolivia.jpg/1280px-Santiago_de_Chiquitos_y_la_Serran%C3%ADa_de_Santiago_-_Chiquitos%2C_Bolivia.jpg', 'Santiago de Chiquitos y su serranía', 3),
    ('external/wikimedia/Chorro San Luis (de frente) - Roboré, Bolivia.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/Chorro_San_Luis_%28de_frente%29_-_Robor%C3%A9%2C_Bolivia.jpg/1280px-Chorro_San_Luis_%28de_frente%29_-_Robor%C3%A9%2C_Bolivia.jpg', 'Cascada Chorro San Luis, Roboré', 4)
  ) as m(path, url, alt, ord)
  returning product_id
)
insert into public.offers (product_id, kind, title, original_price_minor, promotional_price_minor, currency_code, starts_at, ends_at, featured, is_published)
select ins.id, 'normal'::public.offer_kind, 'Hotel Mami Vilma', 25000, 25000, 'BOB', now(), null, true, true
